alter table public.customer_appointment_requests add column appointment_id uuid references public.appointments(id),add column resolved_by uuid references public.profiles(id),add column resolved_at timestamptz,add column response_note text;create index portal_requests_appointment_idx on public.customer_appointment_requests(appointment_id)where appointment_id is not null;create index portal_requests_resolver_idx on public.customer_appointment_requests(resolved_by)where resolved_by is not null;create index portal_requests_company_status_idx on public.customer_appointment_requests(company_id,status,preferred_date);
create or replace function public.approve_customer_appointment_request(p_request uuid,p_scheduled_at timestamptz,p_employee uuid default null,p_note text default null)returns public.appointments language plpgsql security invoker set search_path=''as $$declare c uuid;a public.appointments;r public.customer_appointment_requests;s public.services;begin select company_id into c from public.profiles where id=(select auth.uid())and is_active and role=any(array['proprietario','administrador','gerente','atendente']);if c is null then raise exception'Acesso negado';end if;select*into r from public.customer_appointment_requests where id=p_request and company_id=c for update;if not found or r.status<>'pendente'then raise exception'Solicitação indisponível';end if;if p_scheduled_at<now()then raise exception'Horário inválido';end if;if p_employee is not null and not exists(select 1 from public.profiles where id=p_employee and company_id=c and is_active)then raise exception'Funcionário inválido';end if;if p_employee is not null and exists(select 1 from public.appointments where company_id=c and employee_id=p_employee and scheduled_at=p_scheduled_at and status not in('cancelado','faltou','entregue'))then raise exception'Profissional já possui agendamento neste horário';end if;select*into s from public.services where id=r.service_id and company_id=c;insert into public.appointments(company_id,customer_id,pet_id,service_id,employee_id,scheduled_at,estimated_duration_minutes,expected_price,status,notes,created_by)values(c,r.customer_id,r.pet_id,r.service_id,p_employee,p_scheduled_at,s.estimated_duration_minutes,coalesce(s.base_price,0),'confirmado',concat_ws(E'\n',r.notes,p_note),(select auth.uid()))returning*into a;update public.customer_appointment_requests set status='aprovada',appointment_id=a.id,resolved_by=(select auth.uid()),resolved_at=now(),response_note=p_note where id=r.id;return a;end$$;
create or replace function public.reject_customer_appointment_request(p_request uuid,p_note text)returns void language plpgsql security invoker set search_path=''as $$declare c uuid;begin select company_id into c from public.profiles where id=(select auth.uid())and is_active and role=any(array['proprietario','administrador','gerente','atendente']);if c is null or char_length(trim(p_note))<3 then raise exception'Dados inválidos';end if;update public.customer_appointment_requests set status='recusada',resolved_by=(select auth.uid()),resolved_at=now(),response_note=trim(p_note)where id=p_request and company_id=c and status='pendente';if not found then raise exception'Solicitação indisponível';end if;end$$;
revoke all on function public.approve_customer_appointment_request(uuid,timestamptz,uuid,text),public.reject_customer_appointment_request(uuid,text)from public,anon;grant execute on function public.approve_customer_appointment_request(uuid,timestamptz,uuid,text),public.reject_customer_appointment_request(uuid,text)to authenticated;
create trigger audit_customer_appointment_requests after insert or update or delete on public.customer_appointment_requests for each row execute function private.capture_audit_log();
